-- C-04: departments, locations and their subsidiary assignments.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema organization_master_private;revoke all on schema organization_master_private from public,anon,authenticated,service_role;grant usage on schema organization_master_private to authenticated;
create function organization_master_private.meta(k text)returns table(t text,pk text,links text,fields text[])language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.links,c.fields from(values
 ('departments','departments','department_id','department_subsidiaries',array['name','type','parent_id','is_inactive']),
 ('locations','locations','location_id','location_subsidiaries',array['name','parent_id','country_id']))c(k,t,pk,links,fields)where c.k=$1$$;
create function organization_master_private.allowed(k text,a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();if not exists(select 1 from organization_master_private.meta(k))or(k='locations'and a='delete')then return false;end if;if a='view'then return asset_posting_private.allowed('organization:'||k,'view');end if;return exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='organization:'||k and case a when'create'then m.can_create when'edit'then m.can_edit when'delete'then m.can_delete else false end);exception when insufficient_privilege then return false;end$$;
create function organization_master_private.access(k text,a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.identity();begin if not organization_master_private.allowed(k,a)then raise exception using errcode='42501',message='Requiere permiso explícito para mantener este catálogo.';end if;return sid;end$$;
create function organization_master_private.scope_ids(k text,id bigint)returns bigint[]language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;s bigint[];begin select *into c from organization_master_private.meta(k);execute format('select coalesce(array_agg(distinct sid order by sid),''{}''::bigint[])from(select subsidiary_id sid from public.%I where %I=$1 union select subsidiary_id from public.%I where %I=$1)x where sid is not null',c.t,c.pk,c.links,c.pk)into s using id;return s;end$$;
create function organization_master_private.writable(k text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare s bigint[]:=organization_master_private.scope_ids(k,id);begin return cardinality(s)>0 and not exists(select 1 from unnest(s)x where not exists(select 1 from public.user_subsidiaries us join public.subsidiaries sub using(subsidiary_id)where us.user_id=public.app_user_id()and sub.subsidiary_id=x and sub.is_active));end$$;
create function organization_master_private.visible(k text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.identity();begin return organization_master_private.allowed(k,'view')and(sid=any(organization_master_private.scope_ids(k,id))or(k='locations'and cardinality(organization_master_private.scope_ids(k,id))=0 and inventory_master_private.location(id)));exception when insufficient_privilege then return false;end$$;
create function organization_master_private.used(k text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;f record;b boolean;begin select *into c from organization_master_private.meta(k);for f in select n.nspname,t.relname,a.attname,cardinality(co.conkey)len from pg_constraint co join pg_class t on t.oid=co.conrelid join pg_namespace n on n.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum=co.conkey[1]where co.contype='f'and co.confrelid=to_regclass('public.'||c.t)and t.relname<>c.links loop if f.len<>1 then return true;end if;execute format('select exists(select 1 from %I.%I where %I=$1)',f.nspname,f.relname,f.attname)into b using id;if b then return true;end if;end loop;return false;end$$;
create function organization_master_private.fingerprint(k text,id bigint)returns text language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;l jsonb;begin select *into c from organization_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;execute format('select coalesce(jsonb_agg(to_jsonb(x)order by subsidiary_id),''[]'')from public.%I x where %I=$1',c.links,c.pk)into l using id;return md5(jsonb_build_array(r,l)::text);end$$;
create function organization_master_private.dto(k text,id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin select *into c from organization_master_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;return r||jsonb_build_object('subsidiary_ids',coalesce((select jsonb_agg(x order by (x=(r->>'subsidiary_id')::bigint)desc,x)from unnest(organization_master_private.scope_ids(k,id))x where exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=x)),'[]'),'_revision',organization_master_private.fingerprint(k,id),'_actions',jsonb_build_object('canEdit',organization_master_private.allowed(k,'edit')and organization_master_private.writable(k,id),'canDelete',organization_master_private.allowed(k,'delete')and organization_master_private.writable(k,id)and not organization_master_private.used(k,id)));end$$;
create function public.organization_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform organization_master_private.access(p_catalog,'view');select *into c from organization_master_private.meta(p_catalog);execute format('select coalesce(jsonb_agg(organization_master_private.dto($1,%I)order by %I),''[]'')from public.%I where organization_master_private.visible($1,%I)',c.pk,c.pk,c.t,c.pk)into r using p_catalog;return r;end$$;
create function public.organization_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=organization_master_private.access(p_catalog,'view');refs jsonb;begin
 refs:=jsonb_build_object('organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name,'country_id',s.country_id))from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active),'[]'));
 if p_catalog='locations'then refs:=refs||jsonb_build_object('core/countries',coalesce((select jsonb_agg(jsonb_build_object('country_id',c.country_id,'name',c.name))from public.countries c where exists(select 1 from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active and s.country_id=c.country_id)),'[]'));end if;
 refs:=refs||jsonb_build_object('organization/'||p_catalog,public.organization_master_list(p_catalog));
 return jsonb_build_object('canView',true,'canCreate',organization_master_private.allowed(p_catalog,'create'),'canEdit',organization_master_private.allowed(p_catalog,'edit'),'canDelete',organization_master_private.allowed(p_catalog,'delete'),'references',refs);end$$;
create function public.save_organization_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;sid bigint;oldrow jsonb;data jsonb;r jsonb;subs bigint[];oldsubs bigint[];parent bigint;parentrow jsonb;parscope bigint[];cycle boolean;col text;cols text;vals text;sets text;used boolean;begin
 sid:=organization_master_private.access(p_catalog,case when p_id is null then'create'else'edit'end);select *into c from organization_master_private.meta(p_catalog);
 if p_id<=0 or p_id>9007199254740991 or jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>32000 or exists(select 1 from jsonb_object_keys(p_payload)x where not x=any(c.fields||array['subsidiary_ids','_revision']))then raise exception using errcode='22023',message='Campos de catálogo inválidos.';end if;
 perform pg_advisory_xact_lock(793147,1);perform pg_advisory_xact_lock(793102,1);
 if p_id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using p_id;if oldrow is null or not organization_master_private.visible(p_catalog,p_id)or not organization_master_private.writable(p_catalog,p_id)then raise exception using errcode='42501',message='Catálogo compartido no autorizado para mantenimiento.';end if;if p_payload->>'_revision'is distinct from organization_master_private.fingerprint(p_catalog,p_id)then raise exception using errcode='55000',message='El catálogo cambió. Consúltelo nuevamente.';end if;end if;
 subs:=entity_master_private.ids(p_payload->'subsidiary_ids');
 if not sid=any(subs)or exists(select 1 from unnest(subs)x where not exists(select 1 from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where s.subsidiary_id=x and us.user_id=public.app_user_id()and s.is_active))then raise exception using errcode='42501',message='Seleccione filiales activas autorizadas, incluyendo la actual.';end if;
 data:=coalesce(oldrow,jsonb_build_object('is_inactive',false))||(p_payload-'subsidiary_ids'-'_revision');
 if jsonb_typeof(data->'name')is distinct from'string'or nullif(btrim(data->>'name'),'')is null or length(btrim(data->>'name'))>250 then raise exception using errcode='22023',message='Nombre de catálogo inválido.';end if;data:=data||jsonb_build_object('name',case when p_catalog='departments'then upper(btrim(data->>'name'))else btrim(data->>'name')end);
 foreach col in array array['parent_id','country_id']loop if data->>col=''then data:=jsonb_set(data,array[col],'null');end if;if data->>col is not null and(data->>col!~'^[1-9][0-9]{0,15}$'or(data->>col)::numeric>9007199254740991)then raise exception using errcode='22023',message='Referencia inválida.';end if;end loop;
 if p_catalog='departments'then if coalesce(data->>'type','')not in('Cliente','Interno')or jsonb_typeof(data->'is_inactive')is distinct from'boolean'then raise exception using errcode='22023',message='Tipo u opción de departamento inválidos.';end if;
 else if data->>'country_id'is null or exists(select 1 from public.subsidiaries s where s.subsidiary_id=any(subs)and s.country_id is distinct from(data->>'country_id')::bigint)then raise exception using errcode='42501',message='El país debe coincidir con todas las filiales asignadas.';end if;end if;
 parent:=nullif(data->>'parent_id','')::bigint;
 if parent is not null then
 execute format('select to_jsonb(x)from public.%I x where %I=$1 for share',c.t,c.pk)into parentrow using parent;parscope:=organization_master_private.scope_ids(p_catalog,parent);
 if parentrow is null or not organization_master_private.visible(p_catalog,parent)or not subs<@parscope or(p_catalog='departments'and(parentrow->>'type'is distinct from data->>'type'or(parentrow->>'is_inactive')::boolean))or(p_catalog='locations'and parentrow->>'country_id'is distinct from data->>'country_id')then raise exception using errcode='42501',message='Padre no disponible para el tipo, país o filiales.';end if;
 execute format('with recursive chain(id,parent,path)as(select %I,parent_id,array[%I]from public.%I where %I=$1 union all select x.%I,x.parent_id,c.path||x.%I from public.%I x join chain c on x.%I=c.parent where not x.%I=any(c.path))select exists(select 1 from chain where id=$2)or exists(select 1 from chain where parent=any(path))',c.pk,c.pk,c.t,c.pk,c.pk,c.pk,c.t,c.pk,c.pk)into cycle using parent,p_id;
 if cycle then raise exception using errcode='22023',message='La jerarquía no puede tener ciclos.';end if;end if;
 if p_id is not null then oldsubs:=organization_master_private.scope_ids(p_catalog,p_id);used:=organization_master_private.used(p_catalog,p_id);
 if used and(not oldsubs<@subs or(oldrow->>'subsidiary_id')::bigint is distinct from subs[1]or oldrow->>'parent_id'is distinct from data->>'parent_id'or(p_catalog='departments'and(oldrow->>'type'is distinct from data->>'type'or(not coalesce((oldrow->>'is_inactive')::boolean,false)and(data->>'is_inactive')::boolean)))or(p_catalog='locations'and oldrow->>'country_id'is distinct from data->>'country_id'))then raise exception using errcode='55000',message='El catálogo utilizado conserva origen, tipo, jerarquía y asignaciones.';end if;end if;
 data:=data||jsonb_build_object('subsidiary_id',subs[1]);
 select string_agg(format('%I',x),','),string_agg(format('v.%I',x),','),string_agg(format('%I=v.%I',x,x),',')into cols,vals,sets from unnest(c.fields||array['subsidiary_id'])x;
 if p_id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)v returning to_jsonb(%I.*)',c.t,cols,vals,c.t,c.t)into r using data;p_id:=(r->>c.pk)::bigint;
 else execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)v where x.%I=$2 returning to_jsonb(x)',c.t,sets,c.t,c.pk)into r using data,p_id;end if;
 execute format('delete from public.%I where %I=$1 and not subsidiary_id=any($2)',c.links,c.pk)using p_id,subs;
 execute format('insert into public.%I(%I,subsidiary_id)select $1,x from unnest($2::bigint[])x where not exists(select 1 from public.%I where %I=$1 and subsidiary_id=x)',c.links,c.pk,c.links,c.pk)using p_id,subs;
 return organization_master_private.dto(p_catalog,p_id);end$$;
create function public.delete_organization_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform organization_master_private.access(p_catalog,'delete');perform pg_advisory_xact_lock(793147,1);select *into c from organization_master_private.meta(p_catalog);execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into r using p_id;if r is null or not organization_master_private.visible(p_catalog,p_id)or not organization_master_private.writable(p_catalog,p_id)then raise exception using errcode='42501',message='Catálogo no disponible para eliminar.';end if;if p_revision is distinct from organization_master_private.fingerprint(p_catalog,p_id)or organization_master_private.used(p_catalog,p_id)then raise exception using errcode='55000',message='El catálogo cambió o tiene dependencias.';end if;execute format('delete from public.%I where %I=$1',c.t,c.pk)using p_id;return true;end$$;
-- Close the old inventory write alias for locations; retain other inventory behavior.
alter function public.save_inventory_master(text,jsonb,bigint)set schema inventory_master_private;
create function public.save_inventory_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='locations'then raise exception using errcode='42501',message='Mantenga ubicaciones desde el catálogo organizativo protegido.';end if;return inventory_master_private.save_inventory_master(p_catalog,p_payload,p_id);end$$;
do $$declare t text;p record;col record;k text;pk text;begin foreach t in array array['departments','department_subsidiaries','locations','location_subsidiaries']loop
 k:=case when t like'department%'then'departments'else'locations'end;pk:=case when k='departments'then'department_id'else'location_id'end;
 for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for col in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',col.column_name,col.column_name,col.column_name,col.column_name,t);end loop;
 execute format('create policy organization_master_read on public.%I for select to authenticated using(organization_master_private.visible(%L,%I)%s)',t,k,pk,case when t like'%subsidiaries'then'and subsidiary_id=public.active_subsidiary_id()'else''end);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema organization_master_private from public,anon,authenticated,service_role;grant execute on function organization_master_private.visible(text,bigint)to authenticated;
revoke all on function inventory_master_private.save_inventory_master(text,jsonb,bigint)from public,anon,authenticated,service_role;
revoke all on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.save_inventory_master(text,jsonb,bigint)from public,anon,authenticated,service_role;
grant execute on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text),public.save_inventory_master(text,jsonb,bigint)to authenticated;
notify pgrst,'reload schema';
